from collections import deque
def comps(g,val=0):
    H=len(g);W=len(g[0]);seen=set();cs=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                q=deque([(i,j)]);seen.add((i,j));c=[]
                while q:
                    y,x=q.popleft();c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==val and (ny,nx) not in seen:
                            seen.add((ny,nx));q.append((ny,nx))
                cs.append(c)
    return cs
